A.cards("c9s4",[{"id": "g9-4-standard", "h": "9.4 · Evidence clinic", "c": ["c9-4-core"], "src": ["TB9:9.4"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect the evidence to the event</h4><ul class=\"e2-note-points\"><li>One half-life leaves 50%; two leave 25%.</li><li>A laboratory ratio needs a geological interpretation.</li><li>Different materials and timescales require different isotope systems.</li><li>Different mineral clocks can date different events in one rock.</li><li>A detrital grain can be much older than its host deposit.</li></ul></section><p>Choose both the isotope clock and the geological event being dated.</p>", "examId": "exam2", "traps": ["Name the event being dated and the observation supporting it. A reconstructed sequence is not an official future-exam key."], "media": []}]);
