A.cards("c9s5",[{"id": "g9-5-standard", "h": "9.5 · Evidence clinic", "c": ["c9-5-core"], "src": ["TB9:9.5"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect the evidence to the event</h4><ul class=\"e2-note-points\"><li>Hard parts and rapid burial favor preservation.</li><li>Mold = cavity; cast = later infill.</li><li>Replacement, films, impressions and entombment preserve different evidence.</li><li>Tracks and burrows record behavior rather than preserved bodies.</li><li>An organic-looking shape does not prove a biological origin.</li></ul></section><p>Burial and preservation select which evidence of life survives.</p>", "examId": "exam2", "traps": ["Name the event being dated and the observation supporting it. A reconstructed sequence is not an official future-exam key."], "media": []}]);
A.match("e2-c9-standard-5-bank","c9-5-core","Match each complete source-supported observation or description to the appropriate interpretation. A bank term may be reused if needed.",[["An unfilled cavity reproduces an organism’s shape", "Mold"], ["Minerals fill an existing mold", "Cast"], ["A preserved footprint or burrow", "Trace fossil"], ["Silica takes the place of original wood", "Replacement"], ["Branching manganese-oxide growth", "Inorganic look-alike"]],"Burial and preservation select which evidence of life survives.",["TB9:9.5"],{"examId": "exam2", "mock": false, "topics": ["E2C9S5"], "wordBank": true});
A.mc("e2-c9-standard-5-check","c9-5-core","A rounded mineral mass in sediment contains a preserved clam shell. How should the features be classified?",["*Shell: body fossil; surrounding mass: concretion|The shell records the organism; a concretion is mineral growth and can contain a fossil.", "Shell: trace fossil; surrounding mass: a mold|A preserved shell is body evidence, and the rounded mineral mass is not merely an empty cavity.", "Shell: body fossil; surrounding mass: a shell cast|A cast reproduces a dissolved shell cavity; a rounded mineral mass around a retained shell has a different origin.", "Shell: trace fossil; surrounding mass: a body fossil|The shell is not evidence of an activity such as walking, and mineral growth alone is not an organism."],"The shell records the organism; a concretion is mineral growth and can contain a fossil.",["TB9:9.5"],{"examId": "exam2", "mock": false, "topics": ["E2C9S5"], "media": {"kind": "img", "src": "animations/chapter9/source/9.5-p7-Im2.png", "alt": "Original course illustration for section 9.5, PDF page 7", "cap": "Exploring Geology · 9.5 · PDF p7 · unchanged original figure"}, "sourceFigure": true});
