L.EXAM2.topics.push({"id": "E2C9S7", "ch": 9, "title": "9.7 · Use fossils to correlate rock sequences", "sections": ["9.7"], "concepts": ["c9-7-core"], "sources": ["TB9:9.7"], "media": [{"kind": "img", "src": "animations/chapter9/source/9.7-p2-Im1.png", "alt": "Original course illustration for section 9.7, PDF page 2", "cap": "Exploring Geology · 9.7 · PDF p2 · unchanged original figure"}, {"kind": "img", "src": "animations/chapter9/source/9.7-p4-Im1.png", "alt": "Original course illustration for section 9.7, PDF page 4", "cap": "Exploring Geology · 9.7 · PDF p4 · unchanged original figure"}, {"kind": "img", "src": "animations/chapter9/source/9.7-p5-Im1.png", "alt": "Original course illustration for section 9.7, PDF page 5", "cap": "Exploring Geology · 9.7 · PDF p5 · unchanged original figure"}], "standardChapter9": true});
A.cards("c9s7",[{"id": "g9-7-standard", "h": "9.7 · Evidence clinic", "c": ["c9-7-core"], "src": ["TB9:9.7"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect the evidence to the event</h4><ul class=\"e2-note-points\"><li>Short duration, abundance and wide distribution make a useful index.</li><li>Use the intersection, not the sum, of fossil ranges.</li><li>A gap in one column does not erase the record at another site.</li><li>Overlapping sections can reconstruct a longer regional record.</li><li>Correlate evidence across sites, then account for what differs.</li></ul></section><p>Age constraints tighten where independent fossil ranges overlap.</p>", "examId": "exam2", "traps": ["Name the event being dated and the observation supporting it. A reconstructed sequence is not an official future-exam key."], "media": []}]);
A.match("e2-c9-standard-7-bank","c9-7-core","Match each complete source-supported observation or description to the appropriate interpretation. A bank term may be reused if needed.",[["Short time range and widespread, abundant occurrence", "Useful index fossil"], ["Two unreworked fossils occur in one bed", "Intersection of their time ranges"], ["A matching horizon across two sections", "Correlation"], ["Overlapping local columns assembled into a longer record", "Composite stratigraphic section"]],"Age constraints tighten where independent fossil ranges overlap.",["TB9:9.7"],{"examId": "exam2", "mock": false, "topics": ["E2C9S7"], "wordBank": true});
A.mc("e2-c9-standard-7-check","c9-7-core","Two unreworked species occur together, each with a known fossil range. Which age constraint should be used?",["*The shared interval of their two ranges|Both species must fit the same depositional interval, so use the intersection.", "The full interval covered by either range|The union includes times when only one of the two species existed.", "The full range of the more abundant species|Ignoring the other unreworked species discards an independent age constraint.", "The interval between their first appearances|Part of that interval can predate the later-appearing species and cannot explain their coexistence."],"Both species must fit the same depositional interval, so use the intersection.",["TB9:9.7"],{"examId": "exam2", "mock": false, "topics": ["E2C9S7"], "media": {"kind": "img", "src": "animations/chapter9/source/9.7-p2-Im1.png", "alt": "Original course illustration for section 9.7, PDF page 2", "cap": "Exploring Geology · 9.7 · PDF p2 · unchanged original figure"}, "sourceFigure": true});
