A.cards("c9s8",[{"id": "g9-8-standard", "h": "9.8 · Evidence clinic", "c": ["c9-8-core"], "src": ["TB9:9.8"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect the evidence to the event</h4><ul class=\"e2-note-points\"><li>Time units were recognized before their numerical ages were calibrated.</li><li>Keep periods nested within their correct eras.</li><li>Dated volcanic units can bracket fossil-bearing sediment.</li><li>Cutting and containment place the dike on opposite sides of later events.</li><li>Preserve the historical figure without mixing its dates into current course teaching.</li></ul></section><p>Fossil succession supplies the sequence; dated relationships calibrate it.</p>", "examId": "exam2", "traps": ["Name the event being dated and the observation supporting it. A reconstructed sequence is not an official future-exam key."], "media": []}]);
