A.cards("c9s10",[{"id": "g9-10-standard", "h": "9.10 · Evidence clinic", "c": ["c9-10-core"], "src": ["TB9:9.10"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect the evidence to the event</h4><ul class=\"e2-note-points\"><li>Impact excavates material and redistributes it around the crater.</li><li>Similar processes can have very different early-Earth intensities.</li><li>Free oxygen is chemically different from oxygen bound in rock.</li><li>Oxygen production can drive iron precipitation before abundant atmospheric oxygen accumulates.</li><li>Treat the oxygen curve as an interpretation supported by geological evidence.</li></ul></section><p>Early Earth changed physically, chemically and biologically.</p>", "examId": "exam2", "traps": ["Name the event being dated and the observation supporting it. A reconstructed sequence is not an official future-exam key."], "media": []}]);
