A.cards("c9s11",[{"id": "g9-11-standard", "h": "9.11 · Evidence clinic", "c": ["c9-11-core"], "src": ["TB9:9.11"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect the evidence to the event</h4><ul class=\"e2-note-points\"><li>A microbial construction can preserve biological evidence.</li><li>Diversification and improved preservation both shape the fossil record.</li><li>Reconstruct communities from multiple kinds of preserved evidence.</li><li>A broad extinction requires an explanation extending beyond one species or site.</li><li>Coincident timing, a proposed mechanism and a demonstrated cause are distinct.</li></ul></section><p>Life diversified through changing environments, leaving a selective record.</p>", "examId": "exam2", "traps": ["Name the event being dated and the observation supporting it. A reconstructed sequence is not an official future-exam key."], "media": []}]);
