A.cards("c9s14",[{"id": "g9-14-standard", "h": "9.14 · Evidence clinic", "c": ["c9-14-core"], "src": ["TB9:9.14"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect the evidence to the event</h4><ul class=\"e2-note-points\"><li>Past-event ages inform hazard assessment without giving an exact forecast.</li><li>Use deposits before and after an event to constrain its timing.</li><li>A resource depends on the sequence of processes that formed and preserved it.</li><li>Water age and aquifer-rock age describe different events.</li><li>A useful age must fit both the sample and its archaeological context.</li></ul></section><p>Choose an event and a method before treating an age as useful.</p>", "examId": "exam2", "traps": ["Name the event being dated and the observation supporting it. A reconstructed sequence is not an official future-exam key."], "media": []}]);
