A.cards("c9s15",[{"id": "g9-15-standard", "h": "9.15 · Evidence clinic", "c": ["c9-15-core"], "src": ["TB9:9.15"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect the evidence to the event</h4><ul class=\"e2-note-points\"><li>The basement, erosion surface and cover represent separate events.</li><li>Unconformity type depends on local relationships along the surface.</li><li>Thickness and continuity of recorded time are different properties.</li><li>Date deformation and incision using their own crosscutting evidence.</li><li>The canyon is an exposure of a long, interrupted history.</li></ul></section><p>Ancient wall rocks and recent incision must be dated separately.</p>", "examId": "exam2", "traps": ["Name the event being dated and the observation supporting it. A reconstructed sequence is not an official future-exam key."], "media": []}]);
